using System.Text.Json.Serialization;

namespace NetworkOptimizer.UniFi.Models;

/// <summary>
/// A client's custom icon, set by the user in UniFi Network and generated by Ubiquiti
/// (<c>ai_icon</c> on <c>stat/sta</c>, <c>rest/user</c>, and v2 <c>clients/active</c>).
/// </summary>
public class UniFiAiIcon
{
    [JsonPropertyName("icon_id")]
    public string? IconId { get; set; }

    [JsonPropertyName("manufacturer")]
    public string? Manufacturer { get; set; }

    [JsonPropertyName("model")]
    public string? Model { get; set; }

    /// <summary>The icon rendered at each size; every URL carries a revision token.</summary>
    [JsonPropertyName("assets")]
    public List<UniFiAiIconAsset>? Assets { get; set; }
}

/// <summary>One rendered size of a <see cref="UniFiAiIcon"/>.</summary>
public class UniFiAiIconAsset
{
    [JsonPropertyName("url")]
    public string? Url { get; set; }

    [JsonPropertyName("width")]
    [JsonConverter(typeof(FlexibleIntConverter))]
    public int? Width { get; set; }

    [JsonPropertyName("height")]
    [JsonConverter(typeof(FlexibleIntConverter))]
    public int? Height { get; set; }
}
